import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Accessibility","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/accessibility.md","filePath":"dynamic-record-view/accessibility.md"}'),d={name:"dynamic-record-view/accessibility.md"};function c(n,e,s,l,r,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h1><p>Status: <strong>Partially implemented</strong> — this documents the actual current state honestly, not an aspirational target.</p><h2 id="tabs-implemented" tabindex="-1">Tabs (Implemented) <a class="header-anchor" href="#tabs-implemented" aria-label="Permalink to &quot;Tabs (Implemented)&quot;">​</a></h2><p><code>resources/views/livewire/dynamic-record-view/record-view.blade.php</code> and <code>other-data.blade.php</code> hand-roll tabs (not <code>&lt;flux:tabs&gt;</code>, since Flux Free&#39;s tab component didn&#39;t fit the dynamic tab-count use case here). Both now carry:</p><ul><li><code>role=&quot;tablist&quot;</code> on the tab strip container.</li><li><code>role=&quot;tab&quot;</code>, a stable <code>id=&quot;{primary|other-data}-tab-{key}&quot;</code>, <code>aria-selected</code>, and <code>aria-controls</code> pointing at the matching panel, on each tab <code>&lt;button&gt;</code>.</li><li><code>role=&quot;tabpanel&quot;</code>, a matching <code>id=&quot;{primary|other-data}-tabpanel-{key}&quot;</code>, and <code>aria-labelledby</code> on the rendered panel <code>&lt;div&gt;</code>.</li></ul><p>Not implemented: keyboard arrow-key navigation between tabs (native only via Tab/Shift+Tab through the buttons; no roving tabindex or Left/Right arrow handling). Add this if a real accessibility audit flags it as required — it&#39;s a reasonable next increment, not done in this pass.</p><h2 id="copyable-tooltip-fields-implemented-fixed-this-pass" tabindex="-1"><code>copyable()</code> / <code>tooltip()</code> fields (Implemented, fixed this pass) <a class="header-anchor" href="#copyable-tooltip-fields-implemented-fixed-this-pass" aria-label="Permalink to &quot;`copyable()` / `tooltip()` fields (Implemented, fixed this pass)&quot;">​</a></h2><p>Before this pass, <code>Field::copyable()</code>/<code>tooltip()</code> were fluent no-ops — set on the field definition but never read by <code>resources/views/components/dynamic-record-view/fields-content.blade.php</code>. Fixed:</p><ul><li><code>tooltip()</code> renders as a native <code>title</code> attribute on the field&#39;s wrapper <code>&lt;div&gt;</code> — the simplest accessible tooltip mechanism (no extra JS, works with screen readers via the accessible-name computation, no custom positioning to maintain).</li><li><code>copyable()</code> renders a small icon button next to the value that calls <code>navigator.clipboard.writeText()</code> via a minimal Alpine <code>x-on:click</code>, with an <code>aria-label</code> (&quot;Copy {field label}&quot;). No confirmation toast is wired up — add one if a real &quot;copied!&quot; affordance is wanted; out of scope here.</li></ul><h2 id="dark-mode-implemented-spot-checked" tabindex="-1">Dark mode (Implemented, spot-checked) <a class="header-anchor" href="#dark-mode-implemented-spot-checked" aria-label="Permalink to &quot;Dark mode (Implemented, spot-checked)&quot;">​</a></h2><p>All of this engine&#39;s own Blade files (<code>fields-content.blade.php</code>, <code>content.blade.php</code>, <code>record-view.blade.php</code>, <code>other-data.blade.php</code>, <code>relation-picker-modal.blade.php</code>) use the same <code>dark:</code> token convention as the rest of the app (e.g. <code>resources/views/layouts/app.blade.php</code>&#39;s <code>dark:border-zinc-700</code>/<code>dark:text-zinc-100</code> pairing) — borders/text/background each carry a paired <code>dark:</code> variant, no unstyled dark-mode gaps found.</p><h2 id="rtl-implemented-one-fix-this-pass" tabindex="-1">RTL (Implemented, one fix this pass) <a class="header-anchor" href="#rtl-implemented-one-fix-this-pass" aria-label="Permalink to &quot;RTL (Implemented, one fix this pass)&quot;">​</a></h2><p><code>relation-picker-modal.blade.php</code> used <code>text-left</code> on the candidate list buttons — changed to the logical <code>text-start</code> so it flips correctly under RTL locales. No other <code>ml-</code>/<code>mr-</code>/<code>pl-</code>/<code>pr-</code>/<code>left-</code>/<code>right-</code>/<code>text-left</code>/ <code>text-right</code> usage was found in this engine&#39;s own Blade files.</p><h2 id="not-reached-genuinely-missing" tabindex="-1">Not reached / genuinely missing <a class="header-anchor" href="#not-reached-genuinely-missing" aria-label="Permalink to &quot;Not reached / genuinely missing&quot;">​</a></h2><ul><li>No automated accessibility test (e.g. axe-core via Pest browser testing) was added in this pass — the fixes above were verified by code inspection and the existing feature-test suite (which asserts HTML content, not ARIA semantics). Add an axe-core smoke test if accessibility regressions become a concern.</li><li>No live-region (<code>aria-live</code>) announcement when a tab switch or Link/Unlink mutation completes — a screen reader user gets no explicit audible confirmation beyond the DOM update itself.</li></ul>',15)])])}const b=t(d,[["render",c]]);export{m as __pageData,b as default};
